#!/usr/bin/env python3
"""Render read-only aggregate storage snapshots; no data mutations."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def main():
    base=ROOT/'master-db/reports'
    a=json.loads((base/'supabase-storage-before.json').read_text())
    fields=json.loads((base/'supabase-json-fields.json').read_text())
    mib=lambda n:f'{n/1048576:.3f} MiB'
    lines=['# Supabase storage audit', '', f"Captured: {a['captured_at']}. Database: **{a['database_bytes']:,} bytes ({mib(a['database_bytes'])}; {a['database_bytes']/1e6:.3f} decimal MB)**.", '', f"Read-only full-catalog audit. Exact COUNT(*) for all {len(a['objects'])} physical tables; no materialized views. Ordinary views occupy no stored export data. camera_country_coverage is a live view. Country exports are generated by the retained Edge Function, not stored in a database export table.", '', 'Data size is pg_table_size (heap, TOAST including its index, FSM/VM). Index size is the parent table indexes. Total is their sum. TOAST is shown separately but already included in data size; never sum it twice. Percent denominator is pg_database_size, including catalog/free space. JSON value totals describe values, not additional additive table storage.', '', '| table_name | row_count | data_size | index_size | TOAST (included) | total_size | percent_of_database |', '|---|---:|---:|---:|---:|---:|---:|']
    for x in a['objects']:
        lines.append(f"| {x['nspname']}.{x['relname']} | {x['row_count']} | {mib(x['data_bytes'])} | {mib(x['index_bytes'])} | {mib(x['toast_bytes'])} | {mib(x['total_bytes'])} | {x['total_bytes']/a['database_bytes']*100:.4f}% |")
    lines+=['', '## Top 20 indexes', '', '| Index | Table | Size | Unique / primary | Scans since statistics reset |', '|---|---|---:|---|---:|']
    for x in a['indexes'][:20]:
        lines.append(f"| {x['schema_name']}.{x['index_name']} | {x['table_name']} | {mib(x['size_bytes'])} | {x['indisunique']} / {x['indisprimary']} | {x['scans']} |")
    lines+=['', '## Every JSON/JSONB field', '', '| Field | Rows | Stored value bytes | Logical UTF-8 JSON bytes | Max value bytes |', '|---|---:|---:|---:|---:|']
    for x in fields:
        lines.append(f"| {x['schema_name']}.{x['table_name']}.{x['column_name']} | {x['rows']} | {x['stored_value_bytes']} | {x['logical_json_bytes']} | {x['max_json_bytes']} |")
    lines+=['', '## Optimization decision', '', 'No table/index/data deletion is performed. The database already meets the requested 250–300 MB band. R2 removes static delivery work from Supabase but saves **0 database bytes** directly because no persisted generated exports exist. Canonical/source JSONB is operational provenance and is retained.', '', '| Object | Current size | Safety assessment / prerequisite | Potential savings | Rollback plan |', '|---|---:|---|---:|---|', '| Generated exports / materialized views | 0 | Absent; nothing to remove | 0 | Existing Edge endpoint retained |', '| camera_import_staging | 56 KiB | Empty but pipeline staging contract still needed; keep | negligible | Restore schema from migrations |', '| camera_backup_20261007.* | about 1.72 MiB | Historical rollback snapshot; keep until separate restore drill and retention decision | about 1.72 MiB, unclaimed | Verified off-DB dump plus schema restore before any removal |', '| idx_camera_source_links_source | 1.406 MiB | Prefix overlaps unique (source_id, external_id), but narrower index has actual usage; no proven redundant query-plan cost | at most 1.406 MiB, unclaimed | Saved index definition, recreate concurrently after EXPLAIN/monitoring |', '| Large camera_records / camera_source_links | about 258.42 MiB combined | Valuable live records/provenance; not replaced by compact mobile exports; retain | 0 safe savings established | Existing complete local snapshots; no destructive change |', '| Other indexes with zero scans | See table | Zero scans since reset is not proof of redundancy; preserve uniqueness/spatial/pipeline contracts | unproven | Definitions saved in JSON audit |', '', 'Partitioned root realtime.messages has 0 rows and 0 data/index/total bytes; no foreign tables were found. Its partitions, when present, are listed individually above. Ordinary views: public.camera_country_coverage, extensions.pg_stat_statements, extensions.pg_stat_statements_info, vault.decrypted_secrets. No materialized views were found.', '', 'No raw/import cache or report table has material bulk. camera_sources has only 85 rows but 5.14 MiB allocated; possible dead space requires a separate bloat measurement/maintenance window. VACUUM FULL or table rewrites are not justified during this delivery migration.', '', 'All index definitions, exact byte values, system tables and view inventory are in supabase-storage-before.json. No credentials or raw row contents are included.', '']
    (base/'SUPABASE-STORAGE-AUDIT.md').write_text('\n'.join(lines))
if __name__=='__main__':main()
